import React, { useEffect, useState, useRef, useCallback } from 'react';
import axios from 'axios';
import TopBar from '../components/TopBar';
import FloatingLeaves from '../components/FloatingLeaves';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const formatDate = (d) => new Date(d).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

const MediaThumb = ({ files, alt }) => {
  const first = files?.[0];
  if (!first) return <div className="plant-card-placeholder">Plant</div>;
  const isVideo = /\.(mp4|mov|avi|webm)$/i.test(first);
  if (isVideo) return <video src={`${API}${first}`} className="plant-card-media" muted playsInline />;
  return <img src={`${API}${first}`} alt={alt} className="plant-card-media" loading="lazy" />;
};

const StatCounter = ({ end, label, icon }) => {
  const [count, setCount] = useState(0);
  useEffect(() => {
    let start = 0;
    const inc = Math.max(1, Math.ceil(end / 40));
    const t = setInterval(() => {
      start += inc;
      if (start >= end) { setCount(end); clearInterval(t); }
      else setCount(start);
    }, 40);
    return () => clearInterval(t);
  }, [end]);
  return (
    <div className="stat-card">
      <span className="stat-icon">{icon}</span>
      <div>
        <div className="stat-value">{count}</div>
        <div className="stat-label">{label}</div>
      </div>
    </div>
  );
};

const AutoCarousel = ({ items, renderSlide, slidesPerView = 2, interval = 4000 }) => {
  const [idx, setIdx] = useState(0);
  const timer = useRef(null);
  const [isMobile, setIsMobile] = useState(false);
  const visibleSlides = isMobile ? 1 : slidesPerView;

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth <= 560);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const next = useCallback(() => {
    setIdx(i => (i + 1) % Math.max(1, items.length - visibleSlides + 1));
  }, [items.length, visibleSlides]);

  useEffect(() => {
    if (items.length <= visibleSlides) return;
    timer.current = setInterval(next, interval);
    return () => clearInterval(timer.current);
  }, [items.length, next, interval, visibleSlides]);

  const total = Math.max(1, items.length - visibleSlides + 1);

  return (
    <div>
      <div className="carousel-wrapper">
        <div
          className="carousel-track"
          style={{ transform: `translateX(-${idx * (100 / visibleSlides)}%)` }}
        >
          {items.map((item, i) => (
            <div key={i} style={{ minWidth: `${100 / visibleSlides}%`, padding: '0 6px' }}>
              {renderSlide(item, i)}
            </div>
          ))}
        </div>
      </div>
      {total > 1 && (
        <div className="carousel-dots">
          {Array.from({ length: total }).map((_, i) => (
            <button
              key={i}
              className={`carousel-dot ${idx === i ? 'active' : ''}`}
              onClick={() => setIdx(i)}
              aria-label={`Go to slide ${i + 1}`}
            />
          ))}
        </div>
      )}
    </div>
  );
};

const HomePage = () => {
  const [recent, setRecent] = useState([]);
  const [allPlants, setAllPlants] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      axios.get(`${API}/api/plants/recent`),
      axios.get(`${API}/api/plants`)
    ]).then(([r, a]) => {
      setRecent(r.data);
      setAllPlants(a.data);
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const last7Activity = allPlants.slice(0, 7);

  return (
    <>
      <TopBar />
      <FloatingLeaves />
      <div className="page-container home-container">
        <section className="welcome-panel">
          <div>
            <span className="welcome-kicker">Ecoistic Friendly</span>
            <h1>Welcome Back</h1>
            <p>Keep growing the record of every plant you care for.</p>
          </div>
          <img src="/assets/ecoistic-logo.png" alt="" />
        </section>

        <div className="stats-row">
          <StatCounter end={allPlants.length} label="Plants Added" icon="01" />
          <StatCounter end={allPlants.length * 3} label="Care Updates" icon="02" />
          <StatCounter end={allPlants.length * 3} label="Plants Growing" icon="03" />
          <div className="stat-card">
            <span className="stat-icon">04</span>
            <div>
              <div className="stat-value">Go</div>
              <div className="stat-label">Greener Tomorrow</div>
            </div>
          </div>
        </div>

        <div style={{ marginBottom: 24 }}>
          <div className="section-title">
            <span>New</span> Latest Plant Contributions
            <span style={{ fontSize: '0.72rem', color: 'var(--text-light)', marginLeft: 'auto' }}>Last 10 days</span>
          </div>
          {loading ? (
            <div className="spinner" />
          ) : recent.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state-icon">Plant</div>
              <h3>No recent contributions</h3>
              <p>Be the first to add a plant!</p>
            </div>
          ) : (
            <AutoCarousel
              items={recent}
              interval={4000}
              slidesPerView={2}
              renderSlide={(plant) => (
                <div className="plant-card">
                  <MediaThumb files={plant.files} alt={plant.plantName} />
                  <div className="plant-card-body">
                    <div className="plant-card-name">{plant.plantName}</div>
                    <div className="plant-card-date">Date {formatDate(plant.date)}</div>
                    {plant.report && <div className="plant-card-report">{plant.report}</div>}
                  </div>
                </div>
              )}
            />
          )}
        </div>

        <div>
          <div className="section-title">
            <span>Log</span> Recent Activity Reports
            <span style={{ fontSize: '0.72rem', color: 'var(--text-light)', marginLeft: 'auto' }}>Last 7</span>
          </div>
          {loading ? (
            <div className="spinner" />
          ) : last7Activity.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state-icon">Log</div>
              <h3>No activity yet</h3>
            </div>
          ) : (
            <div className="hscroll-carousel">
              {last7Activity.map((plant, i) => {
                const first = plant.files?.[0];
                const isVideo = first && /\.(mp4|mov|avi|webm)$/i.test(first);
                return (
                  <div className="activity-card" key={plant._id} style={{ animationDelay: `${i * 0.08}s` }}>
                    {first ? (
                      isVideo
                        ? <video src={`${API}${first}`} className="activity-card-thumb" muted playsInline />
                        : <img src={`${API}${first}`} alt={plant.plantName} className="activity-card-thumb" loading="lazy" />
                    ) : (
                      <div className="activity-card-thumb-placeholder">Plant</div>
                    )}
                    <div className="activity-card-info">
                      <div className="activity-card-name">{plant.plantName}</div>
                      <div className="activity-card-date">Date {formatDate(plant.date)}</div>
                      <div className="activity-card-report">{plant.report || 'No report added.'}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default HomePage;
